const LEARN=[{no:"3",t:"Hukuki Bilgilendirme ve Risk Tespit Formu – Mülakat Cevapları (28.09.2026)",url:U.form,st:"applied",for:"E-1"},{no:"4",t:"DD Kapsamında Talep Edilen Belgeler (28.09.2026)",url:U.ddList,st:"shared",for:"E-1"},{no:"1",t:"İş Modeli Nedir ve Neden Analiz Edilir? – Bilgi Notu",url:U.bmcNot,st:"shared",for:"A.1"},{no:"2",t:"İş Modeli Soru Seti – Toplantı Formu (9 blok × 5 soru)",url:U.bmcSoru,st:"shared",for:"A.1"},{no:"Ç1",t:"Hizmet Teklifi – 8 hizmet başlığı ve süreç akışı (Faz 1 Analiz & Strateji → Faz 2 Yapılandırma)",url:U.teklif,st:"shared",for:"Onboarding"},{no:"Ç2.1",t:"EK-1 Mali Yapı ve Finansman Süreçleri – kapsam ve ücretlendirme",url:U.ek1,st:"shared",for:"A.4 / B.4"},{no:"DR",t:"Data Room Yapısı ve Kullanımı – 9 başlık (29.09 maili)",st:"shared",for:"E-1"},{no:"27",t:"Tek Taraflı ve Karşılıklı NDA şablonları (17.08.2026)",st:"applied",for:"E-4"},{no:"DD",t:"Due Diligence Asgari İnceleme Kılavuzu – A.Ş.",st:"planned",for:"E-1"},{no:"32",t:"Kurucu Pay Yapısı, Vesting ve Pay Sahipliği Sözleşmesi – Bilgi Notu",st:"planned",for:"A.3"},{no:"FM",t:"Yazılım ve Model FM Sahipliği: Kurucu / Geliştirici Devri – Bilgi Notu",st:"planned",for:"E-2 / E-3"},{no:"AI",t:"Üretken AI Ürünlerinde KVKK ve EU AI Act – Bilgi Notu",st:"planned",for:"E-6"},{no:"SaaS",t:"SaaS Sözleşme Seti (ToS · abonelik · DPA) – Bilgi Notu",st:"planned",for:"D.1 / E-2"},{no:"5",t:"İş Planı Nedir ve Neden Analiz Edilir? – Bilgi Notu",st:"planned",for:"A.2"},{no:"A.4.2",t:"Yatırımcı Sunumu (Pitch Deck) Bilgi Notu",st:"planned",for:"A.4"},{no:"27b",t:"NDA Kullanım Bilgilendirme Dokümanı",st:"planned",for:"E-4"}];

function viewInsights(){
 const items=allItems(), c=stats(items), ob=onboardStats(); const ents=CLIENT.short;
 const okrAvg=ent=>OKR[ent].map(o=>[o.t,Math.round(o.kr.reduce((a,k)=>a+k[2],0)/o.kr.length)]);
 const krTotal=ents.reduce((a,e)=>a+OKR[e].reduce((x,o)=>x+o.kr.length,0),0);
 const krStarted=ents.reduce((a,e)=>a+OKR[e].reduce((x,o)=>x+o.kr.filter(k=>k[2]>0).length,0),0);
 const krAvgAll=Math.round(ents.reduce((a,e)=>a+okrAvg(e).reduce((x,o)=>x+o[1],0),0)/(ents.length*5));
 const dd=ddAll();
 const riskBands=[["Kritik (≥16)",RISKS.filter(r=>r.p*r.i>=16).length,"var(--red-ink)"],["Yüksek (10–15)",RISKS.filter(r=>{const s=r.p*r.i;return s>=10&&s<16;}).length,"var(--warn)"],["Orta (6–9)",RISKS.filter(r=>{const s=r.p*r.i;return s>=6&&s<10;}).length,"var(--info)"],["Düşük (<6)",RISKS.filter(r=>r.p*r.i<6).length,"var(--success)"]];
 const basis=[["Dokümana dayalı",BASIS_COUNT.doc.length,"var(--success)"],["Beyana dayalı",BASIS_COUNT.beyan.length,"var(--warn)"],["Dayanak yok",BASIS_COUNT.none.length,"var(--neutral)"]]; const basisTot=basis.reduce((a,b)=>a+b[1],0);
 const owners={}; items.forEach(it=>it.docs.forEach((d,i)=>{if(stOf(it,i)==="input"){const k=d.owner.split(" / ")[0].split(" + ")[0];owners[k]=(owners[k]||0)+1;}}));
 const actions=[["Tamamlandı",ACTIONS.filter(a=>a[4]==="done").length],["Devam ediyor",ACTIONS.filter(a=>a[4]==="progress").length],["Girdi bekleniyor",ACTIONS.filter(a=>a[4]==="input"||a[4]==="review").length],["Planlı",ACTIONS.filter(a=>a[4]==="pending").length]];
 const meetingsDone=MEETINGS.filter(m=>m.st==="done").length;
 const mailsDone=MAILS.filter(m=>m[3]==="done").length;
 const months=["Ağu 26","Eyl","Eki 26"]; const counts=[5,3,1];
 return `<div class="page-h"><div><div class="eyebrow">Genel Bakış · Insights</div><h1>Insights</h1><p>İş planı metrikleri (OKR), finansal görünürlük ve genel durum göstergeleri; karar destek ve toplantı gündemini hızlı geçmek için.</p></div><div class="right"><button class="btn" data-view="as-A">İş Planı OKR'ları</button><button class="btn" data-view="as-B">Finansman Yapısı</button><button class="btn" data-view="as-E">Risk Haritası</button></div></div>
 ${sec("A · İş Planı Metrikleri (OKR)","5 bölüm × 4–5 KR · ortalama ilerleme")}
 <div class="tiles"><div class="tile accent"><div class="l">KR ilerlemesi (ort.)</div><div class="v num">${krAvgAll}<small>%</small></div><div class="d" style="color:rgba(255,255,255,.65)">${krStarted}/${krTotal} KR başladı</div></div><div class="tile"><div class="l">Toplam KR</div><div class="v num">${krTotal}</div><div class="d">5 bölüm</div></div><div class="tile"><div class="l">Ciro / bütçe hedefi</div><div class="v num">—</div><div class="d"><span class="status input">İletilmedi</span></div></div><div class="tile"><div class="l">KPI matrisi</div><div class="v num">0<small>/ 5</small></div><div class="d">bölüm bazında kurulacak</div></div><div class="tile"><div class="l">İş Planı dokümanı</div><div class="v num">A.2</div><div class="d"><span class="status input">Meown hedefleri iletilmedi</span></div></div></div>
 <div class="grid2" style="margin-top:12px"><div class="card pad">${lbl("Bölüm bazında KR ilerlemesi")}<div style="height:10px"></div>${hbar(okrAvg(E0))}</div>
 <div class="card pad">${lbl("Öne çıkan KR'lar (hedef · ilerleme)")}<div class="tbl-wrap" style="margin-top:8px"><table><thead><tr><th>Bölüm</th><th>KR</th><th>Hedef</th><th style="min-width:110px">İlerleme</th></tr></thead><tbody>${OKR[E0].flatMap(o=>o.kr.map(k=>({b:o.t,k}))).filter(x=>x.k[2]>0||/DD|bütçe|SHA|marka|KVKK|sözleşme|FM/i.test(x.k[0])).slice(0,10).map(x=>`<tr><td class="muted">${x.b}</td><td><b>${x.k[0]}</b></td><td class="muted" style="font-family:var(--font-mono);font-size:11px">${x.k[1]}</td><td><div class="bar" style="height:6px"><i class="s-done" style="width:${x.k[2]}%"></i></div></td></tr>`).join("")}</tbody></table></div></div></div>
 ${sec("B · Şirket ve Finansal Göstergeler","Teklif, sözleşme ve yazışmalardan")}
 <div class="tiles"><div class="tile accent"><div class="l">Tüzel kişilik</div><div class="v num">1</div><div class="d" style="color:rgba(255,255,255,.65)">MEOWNAI Teknoloji A.Ş. · kuruluş 03.07.2026</div></div><div class="tile"><div class="l">Sermaye</div><div class="v num">335<small>k TL</small></div><div class="d">A %98 · B %2 · ödeme teyidi yok</div></div><div class="tile"><div class="l">Danışmanlık bedeli</div><div class="v num">45<small>k TL/ay</small></div><div class="d">01.10.2026 → 1 yıl · + %3 EK-1</div></div><div class="tile"><div class="l">DD süresi</div><div class="v num">3<small> hafta</small></div><div class="d">28.09.2026 → açık · 1/14 belge</div></div><div class="tile"><div class="l">Finansal belge (Drive)</div><div class="v num">0</div><div class="d">ilk hesap dönemi · mizan talep edildi</div></div><div class="tile"><div class="l">Açık dosya</div><div class="v num">3</div><div class="d">bilgisayar iadesi · pay yapısı · FM devri</div></div></div>
 ${sec("C · Genel Durum Metrikleri","Doküman, fonksiyon, dayanak, DD, risk, iletişim")}
 <div class="tiles"><div class="tile accent"><div class="l">Hizmet planı tamamlanma</div><div class="v num">${c.pct}<small>%</small></div><div style="margin-top:10px">${bar(c)}</div></div><div class="tile"><div class="l">DD belge</div><div class="v num">${dd.ok}<small>/ ${dd.tot}</small></div><div class="d">9 başlık · 1/14 talep edilen belge</div></div><div class="tile"><div class="l">Açık girdi</div><div class="v num">${c.input}</div><div class="d">${Object.entries(owners).map(([k,v])=>`${k.split(" ")[0]} ${v}`).join(" · ")}</div></div><div class="tile"><div class="l">Kritik + yüksek risk</div><div class="v num">${riskBands[0][1]+riskBands[1][1]}<small>/ ${RISKS.length}</small></div><div class="d">pay yapısı · FM devri · marka · KVKK</div></div><div class="tile"><div class="l">Toplantı tutanağı</div><div class="v num">${meetingsDone}<small>/ ${MEETINGS.length}</small></div><div class="d">${mailsDone} teslimat maili</div></div><div class="tile"><div class="l">Onboarding</div><div class="v num">${ob.obPct}<small>%</small></div><div class="d">rehber özümsenme ${ob.lnPct}%</div></div></div>
 <div class="grid2" style="margin-top:12px">
  <div class="card pad">${lbl("Data Room bölümleri · doküman durumu")}<div style="height:10px"></div><div style="display:flex;flex-direction:column;gap:8px">${DATAROOM.map(sct=>stackRow(sct.title,stats(sct.items))).join("")}</div>${legend}</div>
  <div class="card pad">${lbl("Fonksiyonlar · tamamlanma")}<div style="height:10px"></div>${hbar(Object.keys(FUNCTIONS).map(k=>[k,stats(items.filter(i=>i.fn===k)).pct]))}<div style="height:16px"></div>${lbl("Dayanak dağılımı · panel sayısı")}<div style="height:10px"></div>${hbar(basis.map(b=>[b[0],b[1],b[2],b[1]+" panel"]),basisTot)}</div>
  <div class="card pad">${lbl("Due Diligence · başlık bazında belge")}<div style="height:10px"></div>${hbar(ENTS.flatMap(e=>DD[e].map(([g,its])=>[e+" · "+g.replace(/^\d+\.\s*/,"").slice(0,30),its.filter(i=>DD_DONE[e].includes(i)).length,"var(--navy)",`${its.filter(i=>DD_DONE[e].includes(i)).length}/${its.length}`])),10)}</div>
  <div class="card pad">${lbl("Risk dağılımı · O×E bandı")}<div style="height:10px"></div>${hbar(riskBands.map(r=>[r[0],r[1],r[2],r[1]+" risk"]),RISKS.length)}<div style="height:16px"></div>${lbl("Açık aksiyonlar ("+ACTIONS.length+")")}<div style="height:10px"></div>${hbar(actions.map((a,i)=>[a[0],a[1],["var(--success)","var(--warn)","var(--red-ink)","var(--neutral)"][i],a[1]+" aksiyon"]),ACTIONS.length)}</div>
  <div class="card pad">${lbl("Girdi bekleyen · sorumlu bazında")}<div style="height:10px"></div>${hbar(Object.entries(owners).sort((a,b)=>b[1]-a[1]).map(([k,v])=>[k,v,"var(--red-ink)",v+" kalem"]),Math.max(...Object.values(owners),1))}</div>
  <div class="card pad">${lbl("Toplantı ritmi · ay bazında takvim toplantısı (yazılı çıktı: yalnızca 28.09)")}<div style="height:10px"></div><svg class="chart" viewBox="0 0 640 120" role="img" aria-label="Toplantı ritmi">${(()=>{const n=months.length,bw=(640-30)/n;return months.map((m,i)=>{const x=20+i*bw+4,h=counts[i]*20,w=bw-8;return `<rect x="${x}" y="${90-h}" width="${w}" height="${h}" rx="3" fill="${counts[i]?"var(--navy)":"var(--tint-12)"}"><title>${m}: ${counts[i]} toplantı kaydı</title></rect>${counts[i]===0?`<rect x="${x}" y="30" width="${w}" height="60" rx="3" fill="none" stroke="var(--border-strong)" stroke-dasharray="4 3"/>`:""}<text x="${x+w/2}" y="106" text-anchor="middle" style="font-size:9.5px">${m}</text>`;}).join("")+`<line class="grid" x1="20" x2="630" y1="90" y2="90"/>`;})()}</svg><div class="muted">Ağu–Eki 2026'da 9 takvim toplantısı; yalnızca 28.09 mülakatının yazılı çıktısı var. Aylık yönetim toplantısı + tutanak ritmi kurulmalı.</div></div>
 </div>`;}

